 async function removeAssessment(){if(!removal)return;setBusy(true);try{const result=await json('/api/assessments',payload('DELETE',{studentId:removal.studentId,category:removal.category,itemId:removal.itemId}));if(visibleStudent.current===removal.studentId){setAssessments(list=>Object.fromEntries(Object.entries(list).filter(([id])=>!result.ids.includes(Number(id)))));setComments(list=>list.filter(c=>!result.ids.includes(c.itemId)))}setRemoval(null);setMessage('Bedömningen är borttagen.')}catch(e){setMessage((e as Error).message)}finally{setBusy(false)}}
